import {copy,id,now,defaults,categories,emptyDB,ingredient,recipe,solve,convertDoseMode,referenced,validate,normalize,dropsPerMl,recipeRating,sortedRecipes,checkIngredient,checkRecipe} from './model.js'; import {createDevelopmentSession,developmentState,appendDevelopmentEvent,replaceDevelopmentEvent,developmentToRecipe,sessionUsesIngredient,planDevelopmentTargets,correctDevelopmentPlan,registerDevelopmentPlan} from './development.js'; import * as storage from './storage.js';
const $=s=>document.querySelector(s),app=$('#app'),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),fmt=(n,d=2)=>Number(n).toLocaleString('da-DK',{minimumFractionDigits:d,maximumFractionDigits:d});let db,tab='blends',selected,selectedIngredient,selectedDevelopment,editing=false,editBase,ingredientEditing=false,ingredientEditBase,saveN=0,pendingRating=null,freshRecipeId=null,freshIngredientId=null;
const cur=()=>db.recipes.find(x=>x.id===selected),ing=()=>db.ingredients.find(x=>x.id===selectedIngredient),dev=()=>db.developmentSessions.find(x=>x.id===selectedDevelopment); const field=(label,key,v,type='text',x='')=>`<label>${label}<input data-field="${key}" name="${key}" type="${type}" value="${esc(v)}" ${x}></label>`;const opts=(a,v)=>a.map(([x,n])=>`<option value="${esc(x)}" ${x===v?'selected':''}>${esc(n)}</option>`).join('');const doseDisplay=row=>row.mode==='drops'?String(Math.round(Number(row.amount)||0)):(Number(row.amount)||0).toFixed(2);
function rankingEditor(r){const value=pendingRating??recipeRating(r);return `<div class="editor-ranking"><span class="rating-label">Bedømmelse: ${value}/10</span><div class="rating-choices" role="group" aria-label="Vælg ranking"><button class="rating-zero ${value===0?'active':''}" data-a="editrating" data-rating="0" aria-label="0 stjerner" aria-pressed="${value===0}">0</button>${Array.from({length:10},(_,j)=>`<button class="rating-choice ${j<value?'active':''}" data-a="editrating" data-rating="${j+1}" aria-label="${j+1} stjerner" aria-pressed="${value===j+1}">${j<value?'★':'☆'}</button>`).join('')}</div></div>`}
function rankingDisplay(r){const rating=recipeRating(r);return `<span class="blend-rating-display" aria-label="Bedømmelse ${rating} af 10"><span class="rating-score">${rating}/10</span>${rating?`<span class="rating-stars" aria-hidden="true">${'★'.repeat(rating)}</span>`:''}</span>`}
const percentMode=()=>db.settings.percentMode==='weight'?'weight':'volume';
const percentLabel=()=>percentMode()==='weight'?'vægt%':'vol%';
function percentControl(){return `<label class="percent-control">Procentvisning<select data-percent-mode aria-label="Procentvisning"><option value="volume" ${percentMode()==='volume'?'selected':''}>vol%</option><option value="weight" ${percentMode()==='weight'?'selected':''}>vægt%</option></select></label>`}
function percentHeaders(){return percentMode()==='weight'?'<th scope="col" class="preferred-percent">vægt%</th><th scope="col">vol%</th>':'<th scope="col" class="preferred-percent">vol%</th><th scope="col">vægt%</th>'}
function percentCells(grams,ml,mass,volume){const weight=mass?grams/mass*100:0,vol=volume?ml/volume*100:0;return percentMode()==='weight'?`<td class="preferred-percent">${fmt(weight)}</td><td>${fmt(vol)}</td>`:`<td class="preferred-percent">${fmt(vol)}</td><td>${fmt(weight)}</td>`}
const dropText=(ml,rate)=>ml<=0?'—':ml*rate<1?'&lt;1':String(Math.round(ml*rate));
function dataTable(items,mass,volume,digits=2,withTotal=false,ingredientSource=db.ingredients){
 const rows=items.map(item=>{const source=ingredientSource.find(i=>i.id===(item.ingredientId||item.id))||item,rate=item.dropRate||dropsPerMl(source,db.settings);return `<tr><th scope="row">${esc(item.name)}</th><td>${fmt(item.grams,digits)}</td><td>${fmt(item.ml,digits)}</td>${percentCells(item.grams,item.ml,mass,volume)}<td>${dropText(item.ml,rate)}</td></tr>`}).join('');
 const total=withTotal?`<tfoot><tr><th scope="row">Samlet</th><td>${fmt(mass,digits)}</td><td>${fmt(volume,digits)}</td><td>100,00</td><td>100,00</td><td>—</td></tr></tfoot>`:'';
 return `<div class="table-scroll"><table class="data-table"><thead><tr><th scope="col">Ingrediens</th><th scope="col">Gram</th><th scope="col">ml</th>${percentHeaders()}<th scope="col">Dråber ca.</th></tr></thead><tbody>${rows}</tbody>${total}</table></div>`;
}
function developmentComposition(state,digits,ingredients){return dataTable(state.items,state.mass,state.volume,digits,false,ingredients)}
function save(changed=true){
 if(changed)db.lastChangedAt=now();
 const persisted=copy(db);
 if(editBase&&cur()?.locked){const index=persisted.recipes.findIndex(r=>r.id===selected);if(index>=0)persisted.recipes[index]=copy(editBase)}
 if(ingredientEditBase&&ing()?.locked){const index=persisted.ingredients.findIndex(i=>i.id===selectedIngredient);if(index>=0)persisted.ingredients[index]=copy(ingredientEditBase)}
 const n=++saveN;$('#save-status').textContent='Gemmer …';
 return storage.save(persisted).then(()=>{if(n===saveN)$('#save-status').textContent='● Gemt lokalt';return true}).catch(error=>{if(n===saveN)$('#save-status').textContent='Ikke gemt';alert(error);return false});
}
function clearAlert(){const box=$('#alert');box.hidden=true;box.textContent=''}function alert(e){const box=$('#alert');box.hidden=false;box.innerHTML=`<span>${esc(e.message||e)}</span><button class="alert-close" data-dismiss-alert aria-label="Luk fejlmeddelelse">×</button>`;} function result(d,size=d.batch){try{const x=solve(d,db.ingredients,size,db.settings);return `<div class="result-meta"><strong>${fmt(x.strength)} mg/ml</strong><span>PG / VG / ethanol: ${fmt(x.pg,1)} / ${fmt(x.vg,1)} / ${fmt(x.ethanol,1)} %</span></div>${dataTable(x.items,x.total,x.batch,2,true)}`}catch(e){return `<p class="warning">${esc(e.message)}</p>`}}
function finishRecipe(r){
 checkRecipe(r,db.ingredients,db.settings);
 r.rating=pendingRating??recipeRating(r);r.locked=true;r.undo=[];r.redo=[];
 editBase=null;freshRecipeId=null;editing=false;pendingRating=null;save();render();
}
function finishIngredient(i){
 checkIngredient(i);
 const users=referenced(db,i.id),measured=['pg','vg','ethanol','density','strength','dropsOverride'],changed=ingredientEditBase&&measured.some(k=>i[k]!==ingredientEditBase[k]);
 for(const r of users.filter(r=>r.locked))checkRecipe(r,db.ingredients,db.settings);
 if(changed&&users.length&&!confirm(`Ændringen i “${i.name}” påvirker ${users.length} blanding(er): ${users.map(r=>r.name).join(', ')}. Gem alligevel? Du kan i stedet duplikere ingrediensen.`))return false;
 i.locked=true;ingredientEditBase=null;freshIngredientId=null;ingredientEditing=false;save();render();return true;
}
function nav(){
 clearAlert();
 if(editing&&cur()?.locked&&editBase){
  if(confirm('Gem ændringerne i denne blanding?')){
   try{checkRecipe(cur(),db.ingredients,db.settings);cur().rating=pendingRating??recipeRating(cur());editBase=null;save()}catch(error){Object.assign(cur(),copy(editBase));editBase=null;alert(error)}
  }else{Object.assign(cur(),copy(editBase));editBase=null}
 }
 if(ingredientEditing&&ing()?.locked&&ingredientEditBase){
  if(confirm('Gem ændringerne i denne ingrediens?')){
   try{checkIngredient(ing());for(const r of referenced(db,ing().id).filter(r=>r.locked))checkRecipe(r,db.ingredients,db.settings);ingredientEditBase=null;save()}catch(error){Object.assign(ing(),copy(ingredientEditBase));ingredientEditBase=null;alert(error)}
  }else{Object.assign(ing(),copy(ingredientEditBase));ingredientEditBase=null}
 }
 tab=location.hash.slice(1)||'blends';if(!['blends','ingredients','development','more'].includes(tab))tab='blends';
 editing=false;ingredientEditing=false;editBase=null;ingredientEditBase=null;pendingRating=null;freshRecipeId=null;freshIngredientId=null;render();
}
function render(){if(!db)return;document.querySelectorAll('nav a').forEach(a=>{const active=a.hash==='#'+tab;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});if(tab==='ingredients')ingredients();else if(tab==='development')developments();else if(tab==='more')more();else blends();}
function blends(){if(editing&&cur()){app.innerHTML=editor();return}const labels={date:'Oprettelsesdato',name:'Navn',rating:'Bedømmelse'};app.innerHTML=`<div class="page-title"><div><p class="eyebrow">DIT BIBLIOTEK</p><h1>Blandinger</h1></div><div class="blend-actions"><button class="secondary" data-a="sortblends" aria-label="Sortér efter: ${labels[db.sortBy]||labels.date}">Sortér efter: ${labels[db.sortBy]||labels.date}</button><button data-a="new">+ Ny blanding</button></div></div><div class="list">${sortedRecipes(db.recipes,db.sortBy).map(r=>{let t='Mangler ingredienser';try{const x=solve(r.draft,db.ingredients,r.draft.batch,db.settings);t=`${fmt(x.strength)} mg/ml · PG/VG ${fmt(x.pg,0)}/${fmt(x.vg,0)}`}catch{}const date=r.createdAt&&!Number.isNaN(Date.parse(r.createdAt))?new Date(r.createdAt).toLocaleDateString('da-DK'):'Dato mangler';return `<div class="list-row blend-row"><button class="row-title" data-a="open" data-id="${r.id}"><strong>${esc(r.name)}</strong></button><button class="secondary" data-a="duprecipe" data-id="${r.id}" aria-label="Duplikér ${esc(r.name)}">Duplikér</button><button class="secondary" data-a="batch" data-id="${r.id}">Lav batch</button><div class="blend-meta"><small>${r.locked?'Låst':'Kladde'} · ${t}</small><small>Oprettet: ${date}</small>${rankingDisplay(r)}</div></div>`}).join('')||'<div class="empty">Opret ingredienser og din første blanding.</div>'}</div>`}
function editor(){const r=cur(),d=r.draft,isBaseMode=d.nicotineMode==='base',baseOpts=db.ingredients.filter(i=>isBaseMode?(['base','nicotine'].includes(i.category)&&i.strength>0):i.category==='base'&&i.strength===0).map(i=>[i.id,`${i.name}${i.strength?` (${fmt(i.strength)} mg/ml)`:''}`]),doseModes=[['weight','vægt%'],['volume','vol%'],['grams','Gram pr. batch'],['drops','Dråber pr. batch']];return `<section class="editor"><button class="text" data-a="back">‹ Blandinger</button><div class="page-title"><div><p class="eyebrow">${r.locked?'REDIGERING AF LÅST OPSKRIFT':'KLADDE'}</p><h1>${esc(r.name)}</h1></div><div class="toolbar"><button class="secondary" data-a="close">Annuller</button><button data-a="lock">Gem og lås</button></div></div><p class="hint">${r.locked?'Ændringer gemmes først, når du vælger “Gem og lås”.':freshRecipeId===r.id?'Kladde gemmes løbende. Annuller kasserer denne nye blanding.':'Kladde gemmes løbende. Annuller gendanner tilstanden ved åbning.'}</p><div class="editor-grid"><section><div class="fields">${field('Navn','name',r.name)}${field('Batch · ml','batch',d.batch,'number','min="0.1" step="any"')}</div>${rankingEditor(r)}<label>Nikotinmodel<select data-field="nicotineMode"><option value="target" ${!isBaseMode?'selected':''}>Ønsket nikotinstyrke</option><option value="base" ${isBaseMode?'selected':''}>Nikotin bestemt af basen</option></select></label><div class="fields">${!isBaseMode?`${field('Ønsket nikotin · mg/ml','target',d.target,'number','min="0" step="any"')}<label>Nikotinbase · valgfri ved 0 mg/ml<select data-field="nicotineBaseId"><option value="">Vælg</option>${opts(db.ingredients.filter(i=>i.category==='nicotine').map(i=>[i.id,i.name]),d.nicotineBaseId)}</select></label>`:''}<label>${isBaseMode?'Nikotinbase':'Fortyndingsbase'}<select data-field="fillBaseId"><option value="">Vælg</option>${opts(baseOpts,d.fillBaseId)}</select></label></div><h2>Aromaer og tilsætninger</h2><div>${d.rows.map((x,j)=>`<div class="dose-row" data-i="${j}"><label>Ingrediens<select data-row="ingredientId">${opts(db.ingredients.filter(i=>i.category==='aroma'||i.category==='additive').map(i=>[i.id,i.name]),x.ingredientId)}</select></label><label>Mængde<input data-row="amount" type="number" value="${doseDisplay(x)}" min="0" step="${x.mode==='drops'?'1':'.01'}"></label><label>Enhed<select data-row="mode">${opts(doseModes,x.mode)}</select></label><button class="text" data-a="rmrow" data-i="${j}" aria-label="Fjern ingrediensrække">×</button></div>`).join('')}</div><button class="secondary" data-a="addrow">+ Tilføj ingrediens</button><p class="hint">Ved skift af enhed omregnes mængden automatisk. Procent og gram vises med to decimaler; dråber som heltal. Gram og dråber skaleres med batchstørrelsen.</p><label>Note<textarea data-field="note" rows="4">${esc(d.note)}</textarea></label><div class="toolbar"><button class="danger secondary" data-a="delrecipe">Slet opskrift</button></div></section><section class="result-panel"><div class="panel-heading"><h2>Beregnet blanding</h2>${percentControl()}</div><div id="result">${result(d)}</div></section></div></section>`}
function ingredientColumn(title,category,items){return `<section class="ingredient-column"><div class="ingredient-column-title"><h2>${title}</h2><button class="secondary" data-a="newing" data-category="${category}">+ Tilføj</button></div><div class="list ingredient-list">${items.map(x=>`<button class="ingredient-item ${x.id===selectedIngredient?'selected':''}" data-a="opening" data-id="${x.id}"><strong>${esc(x.name)}</strong><small>${categories[x.category]}${x.brand?' · '+esc(x.brand):''}</small></button>`).join('')||'<p class="hint ingredient-empty">Ingen ingredienser endnu.</p>'}</div></section>`}
function ingredients(){const i=ing();if(ingredientEditing&&i){app.innerHTML=ingEditor(i);return}const bases=db.ingredients.filter(x=>x.category==='base'||x.category==='nicotine'),aromas=db.ingredients.filter(x=>x.category==='aroma'),additives=db.ingredients.filter(x=>x.category==='additive');app.innerHTML=`<div class="page-title"><div><p class="eyebrow">DIT BIBLIOTEK</p><h1>Ingredienser</h1></div></div><div class="ingredient-groups">${ingredientColumn('Baser','base',bases)}${ingredientColumn('Aromaer','aroma',aromas)}${ingredientColumn('Tilsætningsstoffer','additive',additives)}</div>`}
function ingEditor(i){const users=referenced(db,i.id);return `<section class="ingredient-editor standalone-editor"><button class="text" data-a="backing">‹ Ingredienser</button><div class="page-title"><div><p class="eyebrow">${i.locked?'REDIGERING AF LÅST INGREDIENS':'NY INGREDIENS'}</p><h1>${esc(i.name)}</h1></div><div class="toolbar"><button class="secondary" data-a="closeing">Annuller</button><button data-a="locking">Gem og lås</button></div></div><p class="hint">${i.locked?'Ændringer gemmes først, når du vælger “Gem og lås”.':freshIngredientId===i.id?'Kladde gemmes løbende. Annuller kasserer denne nye ingrediens.':'Kladde gemmes løbende. Annuller gendanner tilstanden ved åbning.'}</p><div class="fields">${field('Navn','name',i.name)}${field('Producent','brand',i.brand)}<label>Type<select data-field="category">${opts(Object.entries(categories),i.category)}</select></label><label class="check"><input type="checkbox" data-field="have" ${i.have?'checked':''}> Har på lager</label></div><h2>Bærer og måling</h2><div class="fields three">${field('PG %','pg',i.pg,'number','step="any"')}${field('VG %','vg',i.vg,'number','step="any"')}${field('Ethanol %','ethanol',i.ethanol,'number','step="any"')}${field('Vægtfylde g/ml','density',i.density,'number','step="any"')}${field('Egen dråber/ml · valgfri','dropsOverride',i.dropsOverride??'','number','min="0" step="any" placeholder="Automatisk"')}${field('Nikotin mg/ml','strength',i.strength,'number','step="any"')}</div><p class="hint">Tom eller 0 bruger de automatiske dråbekonstanter under Mere.</p><button class="text" data-a="density">Brug standardvægtfylde</button><h2>Købsoplysninger</h2><div class="fields">${field('Købt hos','purchasedFrom',i.purchasedFrom)}${field('Webshop-URL','purchaseUrl',i.purchaseUrl,'url')} ${field('Pris · kr.','purchasePrice',i.purchasePrice,'number','step="0.01"')}${field('Købt mængde · ml','purchaseAmount',i.purchaseAmount,'number','step="any"')}</div><label>Fri note<textarea data-field="note" rows="4">${esc(i.note)}</textarea></label><div class="toolbar"><button class="secondary" data-a="duping">Duplikér</button><button class="danger secondary" data-a="deling">Slet</button></div>${users.length?`<p class="hint">Bruges i: ${users.map(x=>esc(x.name)).join(', ')}. Ved sletning kan du vælge en erstatning.</p>`:''}</section>`}
function developmentIngredients(session){const ids=[session.sourceDraft.fillBaseId];if(session.sourceDraft.nicotineMode==='target')ids.push(session.sourceDraft.nicotineBaseId);return session.ingredientSnapshots.filter(i=>i.category==='aroma'||i.category==='additive').concat(session.ingredientSnapshots.filter(i=>ids.includes(i.id)))}
function developments(){const session=dev();if(session){app.innerHTML=developmentEditor(session);return}app.innerHTML=`<div class="page-title"><div><p class="eyebrow">ARBEJDSPRØVER</p><h1>Udvikling</h1></div><button data-a="newdev" ${db.recipes.length?'':'disabled'}>+ Ny udviklingssession</button></div><p class="hint">Arbejd videre på en lille prøve uden at ændre den oprindelige blanding.</p><div class="list">${db.developmentSessions.map(session=>{let summary='Kan ikke beregnes';try{const state=developmentState(session,db.settings);summary=`${fmt(state.volume)} ml · ${fmt(state.strength)} mg/ml · ${session.events.length} registrering${session.events.length===1?'':'er'}`}catch{}return `<div class="list-row"><button class="row-title" data-a="opendev" data-id="${session.id}"><strong>${esc(session.name)}</strong><small>Fra ${esc(session.sourceName)} · ${summary}</small></button></div>`}).join('')||'<div class="empty">Ingen aktive udviklingssessioner.</div>'}</div>`}
function developmentEditor(session){const state=developmentState(session,db.settings),digits=Math.max(1,Math.ceil(-Math.log10(Number(db.settings.scaleResolution)||.1))),resolution=Number(db.settings.scaleResolution)||.1;return `<section class="development-editor"><button class="text" data-a="backdev">‹ Udvikling</button><div class="page-title"><div><p class="eyebrow">AUTOMATISK GEMT · FRA ${esc(session.sourceName).toUpperCase()}</p><h1>${esc(session.name)}</h1></div><div class="toolbar"><button class="secondary" data-a="sampledev">Prøve udtaget</button><button data-a="adddev">+ Tilføj ingrediens</button><button class="secondary" data-a="targetdev">Beregn mål</button></div></div><div class="capacity-setting"><label>Flaskens kapacitet · ml<input data-dev-capacity type="number" min="0.1" step="any" value="${esc(session.bottleCapacity??session.startVolume)}"></label><span class="hint">Bruges til at advare, hvis et mål kræver mere plads end flasken har.</span></div><div class="development-metrics"><div><small>Aktuel væske</small><strong>${fmt(state.volume,digits)} ml</strong><span>${fmt(state.mass,digits)} g</span></div><div><small>Totalvægt</small><strong>${fmt(state.gross,digits)} g</strong><span>Beholder ${fmt(session.tare,digits)} g</span></div><div><small>Nikotin</small><strong>${fmt(state.strength,2)} mg/ml</strong><span>PG/VG/ethanol ${fmt(state.pg,0)}/${fmt(state.vg,0)}/${fmt(state.ethanol,0)}</span></div></div><div class="development-grid"><section><h2>Registreringer</h2><div class="timeline"><div class="timeline-item"><div><strong>Start</strong><small>${fmt(session.startVolume)} ml · totalvægt ${fmt(session.startGross,digits)} g</small></div></div>${state.steps.map((step,index)=>{const event=step.event,ingredient=session.ingredientSnapshots.find(i=>i.id===event.ingredientId),small=Math.abs(step.deltaGrams)<resolution*3;return `<div class="timeline-item"><div><strong>${index+1}. ${event.type==='withdrawal'?'Prøve udtaget':esc(ingredient?.name||'Ingrediens')+' tilsat'}</strong><small>${event.type==='withdrawal'?`${fmt(Math.abs(step.deltaGrams),digits)} g fjernet`:`${fmt(step.deltaGrams,digits)} g tilsat`} · total ${fmt(session.tare+step.afterMass,digits)} g${event.note?' · '+esc(event.note):''}</small>${small?'<span class="precision-warning">Lille ændring i forhold til vægtens opløsning</span>':''}${event.correctedAt?'<span class="corrected">Rettet registrering</span>':''}</div><button class="text" data-a="editdev" data-id="${event.id}">Ret registrering</button></div>`}).join('')}</div></section><section class="result-panel"><div class="panel-heading"><h2>Aktuel sammensætning</h2>${percentControl()}</div>${developmentComposition(state,digits,session.ingredientSnapshots)}<p class="hint">Resultatet normaliseres til en ny 100 ml-opskrift, når du opretter blandingen.</p></section></div><div class="toolbar development-actions"><button data-a="finishdev">Opret ny blanding fra resultat</button><button class="danger secondary" data-a="deletedev">Slet session</button></div></section>`}
function additionForm(session,event={method:'amount',unit:'grams',amount:'',gross:'',ingredientId:'',note:''}){return `<h2>${event.id?'Ret tilsætning':'Tilføj ingrediens'}</h2><label>Ingrediens<select name="ingredientId">${opts(developmentIngredients(session).map(i=>[i.id,i.name]),event.ingredientId)}</select></label><label>Registreringsmetode<select name="method" data-dev-method><option value="amount" ${event.method!=='weighed'?'selected':''}>Efter mængde</option><option value="weighed" ${event.method==='weighed'?'selected':''}>På vægt</option></select></label><div data-method-panel="amount" ${event.method==='weighed'?'hidden':''}><div class="fields">${field('Mængde','amount',event.amount,'number','min="0" step="any"')}<label>Enhed<select name="unit">${opts([['grams','Gram'],['ml','Milliliter'],['drops','Dråber']],event.unit)}</select></label></div></div><div data-method-panel="weighed" ${event.method!=='weighed'?'hidden':''}>${field('Ny totalvægt · g','gross',event.gross,'number','min="0" step="any"')}</div><label>Note · valgfri<textarea name="note" rows="3">${esc(event.note)}</textarea></label>`}
