function replacementCandidates(item,users){
 return db.ingredients.filter(candidate=>candidate.id!==item.id&&users.every(r=>{
  const d=r.draft;
  if(d.fillBaseId===item.id)return d.nicotineMode==='target'?candidate.category==='base'&&candidate.strength===0:['base','nicotine'].includes(candidate.category)&&candidate.strength>0;
  if(d.nicotineMode==='target'&&d.nicotineBaseId===item.id)return candidate.category==='nicotine'&&candidate.strength>0;
  if(d.rows.some(row=>row.ingredientId===item.id))return ['aroma','additive'].includes(candidate.category);
  return true;
 }));
}
function replaceIngredient(item,users,replacementId){
 const trial=copy(db),replacement=trial.ingredients.find(i=>i.id===replacementId);
 if(!replacement||!replacementCandidates(item,users).some(i=>i.id===replacementId))throw Error('Vælg en kompatibel erstatning.');
 const affected=new Set(users.map(r=>r.id));
 for(const r of trial.recipes.filter(r=>affected.has(r.id))){
  if(r.draft.fillBaseId===item.id)r.draft.fillBaseId=replacementId;
  if(r.draft.nicotineBaseId===item.id)r.draft.nicotineBaseId=replacementId;
  for(const row of r.draft.rows)if(row.ingredientId===item.id)row.ingredientId=replacementId;
 }
 trial.ingredients=trial.ingredients.filter(i=>i.id!==item.id);
 for(const r of trial.recipes.filter(r=>affected.has(r.id)&&r.locked))checkRecipe(r,trial.ingredients,trial.settings);
 if(!confirm(`Erstat “${item.name}” med “${replacement.name}” i ${users.length} blanding(er)? Beregningerne kan ændre sig.`))return false;
 db=trial;selectedIngredient=null;ingredientEditing=false;ingredientEditBase=null;freshIngredientId=null;save();render();return true;
}
