window.addEventListener('hashchange',nav);if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js');

function openTargetHelper(session){
 const state=developmentState(session,db.settings),baseId=session.sourceDraft.fillBaseId,presentIds=new Set(state.items.map(item=>item.id));
 const available=session.ingredientSnapshots.filter(item=>(item.category==='aroma'||item.category==='additive')&&!presentIds.has(item.id));
 const mode=percentMode(),total=mode==='weight'?state.mass:state.volume,d=$('#dialog');
 d.classList.add('target-dialog');
 const newRow=()=>{const used=new Set([...d.querySelectorAll('[data-target-ingredient]')].map(select=>select.value)),next=available.find(item=>!used.has(item.id));return next?`<div class="target-row target-new"><select data-target-ingredient aria-label="Ny ingrediens">${opts(available.map(item=>[item.id,item.name]),next.id)}</select><input data-target-percent aria-label="Mål for ny ingrediens i ${percentLabel()}" type="number" min="0" max="99.999" step="any" placeholder="${percentLabel()}" value=""><button type="button" class="text" data-target-remove aria-label="Fjern nyt mål">×</button></div>`:''};
 d.innerHTML=`<form method="dialog" id="target-form"><h2>Beregn mål</h2><p class="hint">Målfelterne starter med den aktuelle ${percentLabel()}. Kun felter, du ændrer, bliver til direkte mål. Basen fylder automatisk resten, medmindre du ændrer dens mål.</p><h3>Ingredienser i prøven</h3><div class="target-head"><span>Ingrediens · nu</span><span>Mål · ${percentLabel()}</span></div><div class="target-rows">${state.items.map(item=>{const value=Number(((mode==='weight'?item.grams:item.ml)/total*100).toFixed(2));return `<div class="target-row" data-target-current="${esc(item.id)}"><span>${esc(item.name)}<small>${fmt(value)} ${percentLabel()} nu${item.id===baseId?' · fyld-op-base':''}</small></span><input data-target-percent aria-label="Mål for ${esc(item.name)} i ${percentLabel()}" type="number" min="0" max="99.999" step="any" value="${value}"></div>`}).join('')}</div><h3>Tilføj nye ingredienser</h3><div id="target-new-rows"></div><button type="button" class="secondary" data-target-add ${available.length?'':'disabled'}>+ Nyt ingrediensmål</button>${available.length?'':'<p class="hint">Ingen flere aromaer eller tilsætningsstoffer i ingrediensbiblioteket.</p>'}<div class="target-volume"><label>Ønsket slutvolumen · ml (valgfrit)<input data-target-volume type="number" min="0" step="any" placeholder="Brug beregnet volumen"></label><p class="hint">Skalerer hele den beregnede sammensætning. Skal være større end det beregnede volumen.</p></div><div id="target-preview" aria-live="polite"></div><div class="toolbar"><button value="close">Luk beregningshjælp</button></div></form>`;
 const compositionMarkup=plan=>dataTable(plan.composition,plan.finalMass,plan.finalVolume,2,false,session.ingredientSnapshots);
 let activePlan=null,correctedPlan=null;
 const updateTransfer=()=>{const preview=d.querySelector('#transfer-preview'),confirm=d.querySelector('[data-transfer-confirm]');correctedPlan=null;try{
  const adjustments=[...d.querySelectorAll('[data-transfer-ingredient]')].map(row=>({ingredientId:row.dataset.transferIngredient,ml:row.querySelector('input').value}));
  const corrected=correctDevelopmentPlan(session,db.settings,activePlan,adjustments);correctedPlan=corrected;
  preview.innerHTML=`<h3>Faktiske tilsætninger</h3><div class="target-additions">${corrected.additions.map(item=>`<div><strong>${esc(item.name)}${item.ingredientId===baseId?' · automatisk':''}</strong><span>${fmt(item.ml,3)} ml</span><span>${fmt(item.grams,3)} g</span><span>ca. ${Math.round(item.drops)} dråber</span></div>`).join('')||'<p>Ingen tilsætning nødvendig.</p>'}</div><p class="hint">Slutmængde ${fmt(corrected.finalVolume,3)} ml · nikotin ${fmt(corrected.strength,2)} mg/ml.</p>${corrected.overCapacity?`<p class="warning" role="status">Flasken er for lille. Kapaciteten er ${fmt(corrected.capacity,2)} ml.</p>`:''}<h3>Forventet sammensætning efter korrektion</h3>${compositionMarkup(corrected)}`;
  confirm.disabled=corrected.overCapacity||!corrected.additions.length;
 }catch(error){preview.innerHTML=`<p class="warning" role="status">${esc(error.message)}</p>`;confirm.disabled=true}};
 const openTransfer=()=>{if(!activePlan||activePlan.overCapacity||!activePlan.additions.length)return;
  const editable=activePlan.additions.filter(item=>item.ingredientId!==baseId);
  d.querySelector('#target-form').hidden=true;
  d.insertAdjacentHTML('beforeend',`<form method="dialog" id="target-transfer"><h2>Korrigér før registrering</h2><p class="hint">Ret de mængder, du faktisk tilsætter, i ml. Fyld-op-basen beregnes automatisk, så den planlagte slutmængde fastholdes. Gram og dråber vises som hjælp.</p>${editable.length?`<div class="target-head"><span>Ingrediens · foreslået</span><span>Faktisk · ml</span></div>${editable.map(item=>`<div class="target-row" data-transfer-ingredient="${esc(item.ingredientId)}"><span>${esc(item.name)}<small>Foreslået ${fmt(item.ml,3)} ml</small></span><input aria-label="Faktisk mængde for ${esc(item.name)} i ml" type="number" min="0" step="any" value="${Number(item.ml.toFixed(6))}"></div>`).join('')}`:'<p class="hint">Kun fyld-op-basen skal tilsættes.</p>'}<div id="transfer-preview" aria-live="polite"></div><p class="warning">Bekræft først, når du faktisk har tilsat de viste mængder. Registreringerne kan kun rettes som fejlregistreringer.</p><div class="toolbar"><button type="button" class="secondary" data-transfer-back>Tilbage til mål</button><button type="button" data-transfer-confirm>Jeg har tilsat · registrér</button></div></form>`);
  updateTransfer();
 };
 const update=()=>{const preview=d.querySelector('#target-preview'),targets=[],used=new Set([...d.querySelectorAll('[data-target-ingredient]')].map(select=>select.value));activePlan=null;d.querySelector('[data-target-add]').disabled=!available.some(item=>!used.has(item.id));try{
  for(const row of d.querySelectorAll('[data-target-current],.target-new')){
   const value=row.querySelector('[data-target-percent]').value;if(value===''||row.dataset.targetCurrent&&row.dataset.dirty!=='true')continue;
   targets.push({ingredientId:row.dataset.targetCurrent||row.querySelector('[data-target-ingredient]').value,percent:value});
  }
  const desiredVolume=d.querySelector('[data-target-volume]').value;
  if(!targets.length&&desiredVolume===''){preview.innerHTML='<p class="hint">Ændr mindst ét procentmål eller angiv et ønsket slutvolumen for at se beregningen.</p>';return}
  const plan=planDevelopmentTargets(session,db.settings,{targets,percentMode:mode,desiredVolume});activePlan=plan;
  preview.innerHTML=`${desiredVolume!==''?`<p class="hint">Beregnet volumen før skalering: ${fmt(plan.calculatedVolume,2)} ml. Hele sammensætningen skaleres til ${fmt(plan.finalVolume,2)} ml.</p>`:''}<div class="target-summary"><span>Nu: <strong>${fmt(plan.currentVolume,2)} ml</strong></span><span>Efter tilsætning: <strong>${fmt(plan.finalVolume,2)} ml</strong></span><span>Beregnet nikotin: <strong>${fmt(plan.strength,2)} mg/ml</strong></span></div>${plan.overCapacity?`<p class="warning" role="status"><strong>Flasken er for lille.</strong> Målet kræver ${fmt(plan.finalVolume,2)} ml, altså ${fmt(plan.excessMl,2)} ml mere end kapaciteten på ${fmt(plan.capacity,2)} ml. Brug en større beholder eller en mindre prøve.</p>`:`<p class="hint">Inden for flaskens kapacitet på ${fmt(plan.capacity,2)} ml.</p>`}<h3>Beregnede tilsætninger</h3><div class="target-additions">${plan.additions.map(item=>`<div><strong>${esc(item.name)}</strong><span>${fmt(item.ml,3)} ml</span><span>${fmt(item.grams,3)} g</span><span>ca. ${Math.round(item.drops)} dråber</span></div>`).join('')||'<p>Ingen tilsætning nødvendig.</p>'}</div><h3>Forventet sammensætning</h3>${compositionMarkup(plan)}<p class="hint">Dette er kun en beregning. Bekræft først en registrering efter fysisk tilsætning.</p><button type="button" class="secondary" data-target-transfer ${plan.overCapacity||!plan.additions.length?'disabled':''}>Overfør til registreringer</button>`;
 }catch(error){preview.innerHTML=`<p class="warning" role="status">${esc(error.message)}</p>`}};
 d.onclick=event=>{
  if(event.target.closest('[data-target-add]')){d.querySelector('#target-new-rows').insertAdjacentHTML('beforeend',newRow());update();return}
  if(event.target.closest('[data-target-remove]')){event.target.closest('.target-new').remove();update();return}
  if(event.target.closest('[data-target-transfer]')){openTransfer();return}
  if(event.target.closest('[data-transfer-back]')){d.querySelector('#target-transfer').remove();d.querySelector('#target-form').hidden=false;correctedPlan=null;update();return}
  if(event.target.closest('[data-transfer-confirm]'))try{if(!correctedPlan||correctedPlan.overCapacity)return;registerDevelopmentPlan(session,db.settings,correctedPlan);save();d.close();render()}catch(error){updateTransfer();alert(error)}
 };
 d.oninput=event=>{if(event.target.matches('[data-target-current] [data-target-percent]'))event.target.closest('[data-target-current]').dataset.dirty='true';d.querySelector('#target-transfer')?updateTransfer():update()};
 d.onchange=event=>{if(event.target.matches('select'))d.oninput(event)};
 d.onclose=()=>{d.classList.remove('target-dialog');d.onclick=null;d.oninput=null;d.onchange=null};
 d.showModal();update();
}

app.addEventListener('click',event=>{if(event.target.closest('[data-a="targetdev"]'))try{openTargetHelper(dev())}catch(error){alert(error)}});
app.addEventListener('change',event=>{const input=event.target.closest('[data-dev-capacity]');if(!input)return;const capacity=Number(input.value);if(!(capacity>0)){input.value=dev().bottleCapacity??dev().startVolume;alert(Error('Flaskens kapacitet skal være større end nul.'));return}dev().bottleCapacity=capacity;dev().updatedAt=now();clearAlert();save()});
